FloatArray = Java.type("float[]")
DoubleArray = Java.type("double[]")
JavaFloat = Java.type("java.lang.Float")
JavaDouble = Java.type("java.lang.Double")

def to_java_float_array(ruby_array)
  java_floats = Java.type("float[]").new(ruby_array.length)
  ruby_array.each_with_index { |val, i| java_floats[i] = JavaFloat.new(val.to_f) }
  java_floats
end
def to_java_double_array(ruby_array)
  java_doubles = Java.type("double[]").new(ruby_array.length)
  ruby_array.each_with_index { |val, i| java_doubles[i] = val.to_f }
  java_doubles
end
def to_java_string_array(ruby_array)
  java_strings = Java.type("java.lang.String[]").new(ruby_array.length)
  ruby_array.each_with_index { |val, i| java_strings[i] = val }
  java_strings
end
def to_java_int_array(ruby_array)
  java_ints = Java.type("int[]").new(ruby_array.length)
  java_Int = Java.type("java.lang.Integer")
  ruby_array.each_with_index { |val, i| java_ints[i] = java_Int.new(val.to_i) }
  java_ints
end
def to_java_boolean_array(ruby_array)
  java_bools = Java.type("boolean[]").new(ruby_array.length)
  java_Bool = Java.type("java.lang.Boolean")
  ruby_array.each_with_index { |val, i| java_bools[i] = java_Bool.new(val) }
  java_bools
end
